"""Authenticated Ryuu Lua source."""

from __future__ import annotations

from collections.abc import Mapping
import logging
from typing import Optional

from ...constants import DEFAULT_CONFIG, MAX_LUA_BYTES
from ...http import read_response_limited, validated_https_url
from ...security import validate_remote_lua
from ._types import HttpGet


class RyuuSource:
    """Download and validate data-only Lua generated by Ryuu."""

    def __init__(
        self,
        *,
        config: Mapping[str, object],
        http_get: HttpGet,
        logger: logging.Logger,
    ) -> None:
        self.config = config
        self._http_get = http_get
        self.log = logger

    async def fetch_ryuu_lua(self, appid: str) -> Optional[str]:
        """從 Ryuu 下載純 Lua 檔案，回傳已驗證內容或 ``None``。"""

        auth_key = (self.config.get('Ryuu_Auth_Key') or '').strip()  # type: ignore[union-attr]
        if not auth_key:
            self.log.error('未配置 Ryuu_Auth_Key')
            return None
        base = (
            self.config.get('Ryuu_API_Base')
            or DEFAULT_CONFIG['Ryuu_API_Base']
        ).rstrip('/')  # type: ignore[union-attr]
        url = f'{base}/api/download/{appid}?file_type=lua'
        headers = {'X-Auth-Key': auth_key}
        try:
            validated_https_url(base, allowed_hosts={'generator.ryuu.lol'})
            self.log.info('正從 Ryuu 下載 AppID %s 的 lua...', appid)
            response = await self._http_get(
                url,
                headers=headers,
                timeout=60,
                follow_redirects=False,
            )
            if response.status_code == 200:
                raw = await read_response_limited(
                    response,
                    max_bytes=MAX_LUA_BYTES,
                )
                return validate_remote_lua(
                    raw.decode('utf-8'),
                    expected_appid=appid,
                )
            if response.status_code in (401, 403):
                self.log.error(
                    'Ryuu 認證失敗 HTTP %s：請確認 auth_key',
                    response.status_code,
                )
            elif response.status_code == 404:
                self.log.warning('Ryuu 未收錄 AppID %s', appid)
            else:
                self.log.error('Ryuu 下載失敗 HTTP %s', response.status_code)
        except Exception as error:
            self.log.error('Ryuu 請求出錯: %s', error)
        return None


__all__ = ['RyuuSource']
